<template>
  <div class="space-y-5">
    <div class="breadcrumbs text-sm"><ul><li><NuxtLink to="/">Home</NuxtLink></li><li><NuxtLink to="/system-audits">System audit</NuxtLink></li><li>APP history</li></ul></div>
    <div v-if="loading" class="flex justify-center py-20"><span class="loading loading-spinner loading-lg" /></div><div v-else-if="errorMessage" class="alert alert-error"><Icon name="lucide:triangle-alert" class="h-5 w-5" />{{ errorMessage }}</div>
    <template v-else-if="record"><section class="card card-border bg-base-100 shadow-sm"><div class="card-body p-5"><p class="text-sm text-base-content/50">{{ record.item.plan?.company?.name }} · APP {{ record.item.plan?.year }}</p><h1 class="mt-1 text-xl font-bold">{{ record.item.description }}</h1><div class="mt-4 flex flex-wrap gap-2"><span class="badge badge-outline">{{ record.item.reference_no || 'No reference' }}</span><span class="badge badge-outline">{{ money(record.item.total_cost) }}</span></div></div></section><section class="card card-border bg-base-100 shadow-sm"><div class="card-body p-5"><h2 class="card-title text-lg">Record changes</h2><div v-if="!record.audits?.length" class="mt-5 rounded-xl border border-dashed border-base-300 py-12 text-center text-sm text-base-content/50">No field changes have been recorded.</div><ul v-else class="timeline timeline-vertical timeline-compact mt-5"><li v-for="audit in record.audits" :key="audit.id"><div class="timeline-middle"><span class="grid h-7 w-7 place-items-center rounded-full bg-primary text-primary-content"><Icon name="lucide:file-pen-line" class="h-3.5 w-3.5" /></span></div><div class="timeline-end timeline-box mb-5 w-full max-w-4xl border-base-200 bg-base-100"><div class="flex justify-between gap-3"><p class="font-semibold">{{ label(audit.event) }}</p><time class="text-xs text-base-content/50">{{ dateTime(audit.occurred_at) }}</time></div><p class="mt-1 text-sm text-base-content/55">{{ audit.actor?.name || 'System process' }}</p><div class="mt-3 flex flex-wrap gap-2"><span v-for="field in fields(audit)" :key="field" class="badge badge-sm badge-soft">{{ label(field) }}</span></div></div><hr /></li></ul></div></section></template>
  </div>
</template>
<script setup>
definePageMeta({ layout: 'default' }); useHead({ title: 'APP audit history' }); const route = useRoute(); const api = useSystemAuditHelper(); const { can } = useCheckPermission(); const loading = ref(true); const errorMessage = ref(''); const record = ref(null)
const label = value => String(value || '').replaceAll('_', ' ').toLowerCase().replace(/\b\w/g, letter => letter.toUpperCase()); const money = value => new Intl.NumberFormat('en-ZW', { style: 'currency', currency: 'USD' }).format(Number(value || 0)); const dateTime = value => value ? new Intl.DateTimeFormat('en-ZW', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '—'; const fields = audit => [...new Set([...Object.keys(audit.old_values || {}), ...Object.keys(audit.new_values || {})])]
onMounted(async () => { if (!can('can.access.systemaudits')) { errorMessage.value = 'You do not have permission to view system audits.'; loading.value = false; return } const { data, error } = await api.getAppItem(route.params.uuid); loading.value = false; if (error || data?.status === false) errorMessage.value = error?.data?.message || data?.message || 'APP history could not be loaded.'; else record.value = data.data })
</script>
